from ledgerlib.apply_payment import apply_payment


def test_example():
    invoices = [("INV-000010", "2024-01-05", 30, 6000), ("INV-000011", "2024-01-20", 30, 6000)]
    assert apply_payment(10000, invoices) == ({"INV-000010": 6000, "INV-000011": 4000}, 0)


def test_overpayment():
    assert apply_payment(7000, [("INV-000012", "2024-02-01", 14, 5000)]) == ({"INV-000012": 5000}, 2000)


def test_negative_payment_raises():
    with pytest.raises(ValueError):
        apply_payment(-1, [("INV-000013", "2024-02-01", 14, 5000)])


def test_exact_payment():
    assert apply_payment(5000, [("INV-000014", "2024-02-01", 14, 5000)]) == ({"INV-000014": 5000}, 0)


def test_skips_non_positive_open():
    invoices = [("INV-A", "2024-01-01", 0, 0), ("INV-B", "2024-01-02", 0, -100), ("INV-C", "2024-01-03", 0, 3000)]
    assert apply_payment(3000, invoices) == ({"INV-C": 3000}, 0)


def test_orders_by_due_date_not_input_order():
    # INV-late is dated first but has longer net days -> later due date.
    invoices = [("INV-late", "2024-01-01", 60, 2000), ("INV-early", "2024-01-10", 14, 2000)]
    # due dates: INV-late 2024-03-01, INV-early 2024-01-24 -> INV-early first
    assert apply_payment(2000, invoices) == ({"INV-early": 2000}, 2000)


def test_zero_payment():
    assert apply_payment(0, [("INV-000015", "2024-02-01", 14, 5000)]) == ({}, 0)


def test_empty_invoices():
    assert apply_payment(4000, []) == ({}, 4000)
